In the following example, a  is rendered with a SfListView component as its popup content.

<SfDropDownButton CssClass="e-caret-hide" IconCss="e-icons e-down">
  <PopupContent>
    <SfListView ID="listview" DataSource="@Data" ShowCheckBox="true">
      <ListViewFieldSettings Text="Text" TValue="ListData"></ListViewFieldSettings>
    </SfListView>
  </PopupContent>
</SfDropDownButton>

@code {
  public class ListData
  {
    public string Text { get; set; }
    public string Id { get; set; }
    public string Class { get; set; }
  }

  public List<ListData> Data = new List<ListData>
  {
    new ListData{ Class = "data", Text = "Print", Id = "data1" },
    new ListData{ Class = "data", Text = "Save As", Id = "data2" },
    new ListData{ Class = "data", Text = "Update Folder", Id = "data3" },
    new ListData{ Class = "data", Text = "Reply", Id = "data4" }
  };
}

The following example demonstrates how to start the progress on a button.

<SfProgressButton @ref="ProgressButtonRef" Content="Start Progress"></SfProgressButton>
<button class="e-btn" @onclick="Start">Start</button>
@code {
    private SfProgressButton ProgressButtonRef;
    private async Task Start()
    {
        // Starts the progress at 20%
        await this.ProgressButtonRef.StartAsync(20);
    }
}

The following example demonstrates how to stop the progress on a button.

<SfProgressButton @ref="ProgressButtonRef" Content="Process"></SfProgressButton>
<button class="e-btn" @onclick="Start">Start</button>
<button class="e-btn" @onclick="Stop">Stop</button>
@code {
    private SfProgressButton ProgressButtonRef;
    private async Task Start()
    {
        await this.ProgressButtonRef.StartAsync(10);
    }
    private async Task Stop()
    {
        await this.ProgressButtonRef.StopAsync();
    }
}

The following example demonstrates how to focus the progress button.

<SfProgressButton @ref="ProgressButtonRef" Content="Focus Me"></SfProgressButton>
<button class="e-btn" @onclick="FocusBtn">Focus Progress Button</button>
@code {
    private SfProgressButton ProgressButtonRef;
    private async Task FocusBtn()
    {
        await this.ProgressButtonRef.FocusAsync();
    }
}

The following example demonstrates how to complete the progress on a button.

<SfProgressButton @ref="ProgressButtonRef" Content="Process"></SfProgressButton>
<button class="e-btn" @onclick="Start">Start</button>
<button class="e-btn" @onclick="Complete">Complete</button>
@code {
    private SfProgressButton ProgressButtonRef;
    private async Task Start()
    {
        await this.ProgressButtonRef.StartAsync(20);
    }
    private async Task Complete()
    {
        await this.ProgressButtonRef.EndProgressAsync();
    }
}

The following example demonstrates how to programmatically click the button.

<SfProgressButton @ref="ProgressButtonRef" Content="Click Target" OnClick="@OnClickHandler"></SfProgressButton>
<button class="e-btn" @onclick="TriggerClick">Click Progress Button</button>
@code {
    private SfProgressButton ProgressButtonRef;
    private bool isClicked;
    private async Task TriggerClick()
    {
        await this.ProgressButtonRef.ClickAsync();
    }
    private void OnClickHandler(Microsoft.AspNetCore.Components.Web.MouseEventArgs args)
    {
        // This will be executed when ClickAsync is called.
        isClicked = true;
    }
}

In the below code example, a  component is rendered with a  component as .

<SfSplitButton CssClass="e-caret-hide" IconCss="e-icons e-down">
<PopupContent>
<SfListView ID="listview" DataSource="@Data" ShowCheckBox="true">
<ListViewFieldSettings Text="Text" TValue="ListData"></ListViewFieldSettings>
</SfListView>
</PopupContent>
</SfSplitButton>
@code {
public List<ListData> Data = new List<ListData>{
new ListData{ Class = "data", Text = "Print", Id = "data1" },
new ListData{ Class = "data", Text = "Save As", Id = "data2" },
new ListData{ Class = "data", Text = "Update Folder", Id = "data3" },
new ListData{ Class = "data", Text = "Reply", Id = "data4" }
};
public class ListData {
public string Text { get; set; }
public string Id { get; set; }
public string Class { get; set; }
}
}

The following code example demonstrates how to add new items to the .

<SfSplitButton @ref="SplitButton" Content="Save">
    <DropDownMenuItems>
        <DropDownMenuItem Text="Save as..." />
    </DropDownMenuItems>
</SfSplitButton>
@code {
    private SfSplitButton SplitButton;
    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            List<DropDownMenuItem> newItems = new List<DropDownMenuItem>
            {
                new DropDownMenuItem { Text = "Save and Close" },
                new DropDownMenuItem { Text = "Save and New" }
            };
            SplitButton.AddItems(newItems);
        }
    }
}

The following code example demonstrates how to remove items from the .

<SfSplitButton @ref="SplitButton" Content="File">
    <DropDownMenuItems>
        <DropDownMenuItem Text="Open" />
        <DropDownMenuItem Text="Save" />
        <DropDownMenuItem Text="Delete" />
    </DropDownMenuItems>
</SfSplitButton>
<button @onclick="RemoveItem">Remove Item</button>
@code {
    private SfSplitButton SplitButton;
    private void RemoveItem()
    {
        SplitButton.RemoveItems(new List<string> { "Delete" });
    }
}

The following code example demonstrates how to toggle the dropdown programmatically.

<SfSplitButton @ref="SplitButton" Content="Tools">
    <DropDownMenuItems>
        <DropDownMenuItem Text="Run" />
        <DropDownMenuItem Text="Debug" />
    </DropDownMenuItems>
</SfSplitButton>
<button @onclick="ToggleDropdown">Toggle Dropdown</button>
@code {
    private SfSplitButton SplitButton;
    private void ToggleDropdown()
    {
        SplitButton.Toggle();
    }
}
